public final class RepositoryMediaProvider implements MediaProvider{private final ExtensionRecord ext;public RepositoryMediaProvider(ExtensionRecord e){ext=e;}public String id(){return ext.id;}public String displayName(){return ext.name;}public String health(){return ext.searchable()?(ext.playable()?"Search + playback contract ready":"Search ready · playback not declared"):"Metadata only · search contract missing";}public boolean supportsPlayback(){return ext.playable();}public List<AnimeItem> search(String q)throws Exception{if(!ext.searchable())throw new IllegalStateException("Extension does not declare a compatible searchUrl");String target=expand(ext.searchUrl,q,"0",0);HttpURLConnection c=(HttpURLConnection)new URL(target).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(12000);int code=c.getResponseCode();if(code!=200)throw new IOException("Provider HTTP "+code);BufferedReader r=new BufferedReader(new InputStreamReader(c.getInputStream()));StringBuilder b=new StringBuilder();String line;while((line=r.readLine())!=null&&b.length()<750000)b.append(line);r.close();Object parsed=new JSONTokener(b.toString()).nextValue();JSONArray a;if(parsed instanceof JSONArray)a=(JSONArray)parsed;else{JSONObject root=(JSONObject)parsed;a=root.optJSONArray("results");if(a==null)a=root.optJSONArray("items");if(a==null)a=root.optJSONArray("data");if(a==null)throw new JSONException("Search response does not contain a compatible result array");}List<AnimeItem> out=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;String itemId=first(o,"id","slug","url");String title=first(o,"title","name");if(title.length()==0)continue;out.add(new AnimeItem(itemId.length()==0?String.valueOf(i):itemId,title,first(o,"summary","description","synopsis"),ext.id,o.optInt("episodes",o.optInt("episodeCount",0))));}return out;}public String resolveMediaUrl(String itemId,int episode)throws Exception{if(!ext.playable())throw new UnsupportedOperationException("This extension did not declare a playback/media URL contract");String target=expand(ext.playbackUrl,"",itemId,episode);if(!target.startsWith("https://"))throw new IOException("Playback contract must resolve to HTTPS");if(target.endsWith(".mp4")||target.endsWith(".m3u8")||target.endsWith(".webm"))return target;HttpURLConnection c=(HttpURLConnection)new URL(target).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(12000);c.setRequestProperty("Accept","application/json,video/*,*/*");int code=c.getResponseCode();if(code<200||code>=300)throw new IOException("Playback resolver HTTP "+code);String type=c.getContentType();if(type!=null&&type.toLowerCase().startsWith("video/"))return target;BufferedReader r=new BufferedReader(new InputStreamReader(c.getInputStream()));StringBuilder b=new StringBuilder();String line;while((line=r.readLine())!=null&&b.length()<500000)b.append(line);r.close();JSONObject o=new JSONObject(b.toString());String url=first(o,"url","streamUrl","mediaUrl","videoUrl","file");if(!url.startsWith("https://"))throw new IOException("Playback response did not provide an HTTPS media URL");return url;}private String expand(String t,String query,String id,int ep)throws Exception{return t.replace("{query}",URLEncoder.encode(query==null?"":query,"UTF-8")).replace("{id}",URLEncoder.encode(id==null?"":id,"UTF-8")).replace("{episode}",String.valueOf(ep));}private String first(JSONObject o,String... keys){for(String k:keys){String v=o.optString(k,"");if(v!=null&&v.length()>0&&!"null".equalsIgnoreCase(v))return v;}return "";}}
